const Card: React.FC<{
  index: number;
  totalProgress: number;
  cardGap: number;
  headline: string;
}> = ({ index, totalProgress, cardGap, headline }) => {
  // Calculate local phase for this card
  // Cycle is 0 -> 4 now (4 cards).
  const shiftedProgress = (totalProgress + index) % 4;
  
  // Determine current segment
  const segment = Math.floor(shiftedProgress);
  const t = shiftedProgress % 1; // 0 to 1 within segment
  
  // Easing
  const ease = Easing.bezier(0.25, 0.1, 0.25, 1);
  const smoothT = ease(t);

  // Constants
  const OFF_X = PHONE_WIDTH + cardGap; // Distance from center to side position
  const EXIT_OFFSET = 1600; // Distance to move fully off screen
  
  let x = 0;
  let y = 0;
  let scale = 1;
  let opacity = 1;
  let zIndex = 0;
  let radius = 10;
  
  if (segment === 0) {
    // Phase 0: Off-Left -> Left (Enter)
    // Start: x = -EXIT_OFFSET
    // End: x = -OFF_X
    x = interpolate(smoothT, [0, 1], [-EXIT_OFFSET, -OFF_X]);
    zIndex = 1;
    radius = 10;
    // Fade in as it approaches the "Left" visible slot
    opacity = interpolate(smoothT, [0, 0.5, 1], [0, 0.8, 0.8]);

  } else if (segment === 1) {
    // Phase 1: Left -> Center (Focus)
    // Start: x = -OFF_X
    // End: x = 0
    x = interpolate(smoothT, [0, 1], [-OFF_X, 0]);
    zIndex = 2; // Move to front
    radius = interpolate(smoothT, [0, 1], [10, CORNER_RADIUS - (BEZEL_WIDTH/2)]);
    opacity = interpolate(smoothT, [0, 1], [0.8, 1]);
    
  } else if (segment === 2) {
    // Phase 2: Center -> Right (Unfocus)
    // Start: x = 0
    // End: x = OFF_X
    x = interpolate(smoothT, [0, 1], [0, OFF_X]);
    zIndex = 1; // Move behind
    radius = interpolate(smoothT, [0, 1], [CORNER_RADIUS - (BEZEL_WIDTH/2), 10]);
    opacity = interpolate(smoothT, [0, 1], [1, 0.8]);

  } else {
    // Phase 3: Right -> Off-Right (Exit)
    // Start: x = OFF_X
    // End: x = EXIT_OFFSET
    x = interpolate(smoothT, [0, 1], [OFF_X, EXIT_OFFSET]);
    zIndex = 0;
    radius = 10;
    // Fade out as it leaves the "Right" visible slot
    opacity = interpolate(smoothT, [0, 0.5], [0.8, 0]);
  }
  
  return (
    <div
      style={{
        position: "absolute",
        width: PHONE_WIDTH - BEZEL_WIDTH, // Fit inside bezel
        height: PHONE_HEIGHT - BEZEL_WIDTH,
        left: (1920 - (PHONE_WIDTH - BEZEL_WIDTH)) / 2, // Center on screen
        top: (1080 - (PHONE_HEIGHT - BEZEL_WIDTH)) / 2,
        transform: `translateX(${x}px) translateY(${y}px) scale(${scale})`,
        borderRadius: radius,
        zIndex,
        opacity,
        boxShadow: "0 10px 40px rgba(0,0,0,0.2)",
        overflow: "hidden",
        backgroundColor: "white",
        // Optimize for smooth movement
        willChange: "transform, borderRadius",
      }}
    >
      <CardContent type={index % 4} headline={headline} />
    </div>
  );
};

const PhoneCarousel: React.FC<PhoneCarouselProps> = ({
  backgroundColor = "#2b6aff",
  transparentBackground = false,
  durationInSeconds = 9,
  phoneBorderColor = "#000000",
  cardGap = 120,
  headlineBarrons = "Bets on Asia. You Should Bet on Uber.",
  headlineWSJ = "What You Should Do About the Stock Market's Giant Problem",
  headlineMarketWatch = "Is the Nippon Steel bid dead? Here's the latest.",
  headlineNYT = "The Era of Generative AI has begun. What's next?",
}) => {
  useFontLoader(["Playfair Display", "Inter"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  
  // Normalize frame to 0..4 cycle (4 cards)
  const progress = (frame % totalFrames) / totalFrames * 4;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Gather headlines in order
  const headlines = [headlineBarrons, headlineWSJ, headlineMarketWatch, headlineNYT];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Cards Layer */}
      <AbsoluteFill>
         {/* Render 4 Cards */}
         {[0, 1, 2, 3].map((i) => (
           <Card 
             key={i} 
             index={i} 
             totalProgress={progress} 
             cardGap={cardGap}
             headline={headlines[i]}
           />
         ))}
      </AbsoluteFill>

      {/* Phone Frame Overlay (Static) */}
      <div
        style={{
          position: "absolute",
          left: (width - PHONE_WIDTH) / 2,
          top: (height - PHONE_HEIGHT) / 2,
          width: PHONE_WIDTH,
          height: PHONE_HEIGHT,
          zIndex: 50, // Always on top of cards
          pointerEvents: "none",
          filter: "drop-shadow(0 20px 50px rgba(0,0,0,0.5))"
        }}
      >
        <PhoneFrameSVG color={phoneBorderColor} />
      </div>
      
    </AbsoluteFill>
  );
};

export default PhoneCarousel;